type Sex="Macho"|"Fêmea";
type BirdRow={id:number;name:string;sex:Sex;ring:string;birth?:string;father:string;mother:string;lineage:string;status:string;ancestors?:string[];indices?:Record<string,number>;song?:number;production?:number;fertility?:number;offspring?:number;family?:number};
const nameAliases:Record<string,string>={PARAGUAY:"PARAGUAI",AGTAHA:"AGATHA",GYPSI:"GIPSY",TEMPLO:"TEMPLOF3"};
function nameKey(name:string){const normalized=name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/\bJUNIOR\b/gi,"JR").replace(/[^A-Z0-9]/gi,"").toUpperCase();return nameAliases[normalized]||normalized}
function ringKey(ring:string){return ring.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9]/gi,"").toUpperCase()}
const offspringIndex=new Map<string,OffspringRecord[]>();offspringRecords.forEach(record=>{[record[3],record[4]].forEach(parent=>{const key=nameKey(parent),rows=offspringIndex.get(key)||[];rows.push(record);offspringIndex.set(key,rows)})});
function offspringFor(name:string){return offspringIndex.get(nameKey(name))||[]}
function productionSummary(name:string){const rows=offspringFor(name),parent=nameKey(name),partners=new Set(rows.map(r=>nameKey(nameKey(r[3])===parent?r[4]:r[3]))),years=[...new Set(rows.map(r=>r[2]).filter((x):x is number=>x!==null))].sort(),byYear=years.map(y=>[y,rows.filter(r=>r[2]===y).length] as [number,number]);return{rows,total:rows.length,males:rows.filter(r=>r[5]==="M").length,females:rows.filter(r=>r[5]==="F").length,unknown:rows.filter(r=>r[5]==="I").length,partners:partners.size,years,byYear,first:rows[0]?.[1]||"",last:rows.at(-1)?.[1]||""}}
function topProducers(role:3|4){const totals=new Map<string,{name:string,count:number}>();offspringRecords.forEach(r=>{const key=nameKey(r[role]),old=totals.get(key);totals.set(key,{name:old?.name||r[role],count:(old?.count||0)+1})});return[...totals.values()].sort((a,b)=>b.count-a.count).slice(0,5)}
const officialParentage:Record<string,{father:string;mother:string}>={EROS:{father:"JUCA",mother:"MIMOSA"}};
function resolvedAncestors(ancestors:readonly string[]){const result=[...ancestors];result.slice(0,4).forEach((name,i)=>{const official=officialParentage[nameKey(name)];if(official){result[4+i*2]=official.father;result[5+i*2]=official.mother}});return result}
function historicalRecords(active:BirdRow[]){
 const known=new Set(active.map(b=>nameKey(b.name))),records=new Map<string,{name:string;sex:Sex;father:string;mother:string}>();
 const put=(name:string,sex:Sex,father="",mother="")=>{if(!name)return;const key=nameKey(name),old=records.get(key),official=officialParentage[key];records.set(key,{name:old?.name||name,sex:old?.sex||sex,father:official?.father||old?.father||father,mother:official?.mother||old?.mother||mother})};
 badgePedigrees.forEach(p=>{const a=resolvedAncestors(p.ancestors);put(p.name,"Macho",p.father,p.mother);put(p.father,"Macho",a[0],a[1]);put(p.mother,"Fêmea",a[2],a[3]);a.slice(0,4).forEach((name,i)=>put(name,i%2===0?"Macho":"Fêmea",a[4+i*2],a[5+i*2]));a.slice(4).forEach((name,i)=>put(name,i%2===0?"Macho":"Fêmea"))});
 let id=-1;return[...records.entries()].filter(([key])=>!known.has(key)).map(([,r])=>({id:id--,...r,ring:"Registro histórico",lineage:"Genealogia dos crachás",status:"Ancestral"} as BirdRow));
}
const soldBirds=new Set(["BEGONIA","DINASTIA","GANDHY"]);
const applyKnownStatus=(b:BirdRow):BirdRow=>soldBirds.has(nameKey(b.name))?{...b,status:"Vendido"}:b;
const applyOfficialRules=(b:BirdRow):BirdRow=>{const official=officialParentage[nameKey(b.name)];return {...b,...(official||{}),...(b.ancestors?{ancestors:resolvedAncestors(b.ancestors)}:{})}};
const activeSeed:BirdRow[]=importedPlantel.map(b=>{const pedigree=badgePedigrees.find(p=>p.name.localeCompare(b.name,"pt-BR",{sensitivity:"base"})===0);return applyKnownStatus(applyOfficialRules({...b,sex:b.sex as Sex,indices:{...b.indices},...(pedigree?{father:pedigree.father,mother:pedigree.mother,ancestors:resolvedAncestors(pedigree.ancestors)}:{})}))});
const initialBirds:BirdRow[]=[...activeSeed,...historicalRecords(activeSeed)];
const isHistorical=(b:BirdRow)=>b.status==="Ancestral";
const isBreedable=(b:BirdRow)=>b.status==="Matriz"||b.status==="Reprodutor";
const isActive=isBreedable;
const alphaBirds=(rows:BirdRow[])=>[...rows].sort((a,b)=>a.name.localeCompare(b.name,"pt-BR",{sensitivity:"base",numeric:true}));
const SUPABASE_URL="https://rxetfbsvnyzdcyuzhmfi.supabase.co",SUPABASE_KEY="sb_publishable_EffrEgdpf9_YxTAySUnCqA_p5Bu_Q7p";
const token=()=>localStorage.getItem("apolo-access-token")||"";
const apiHeaders=()=>({"content-type":"application/json","authorization":`Bearer ${token()}`});
const persistBird=(bird:BirdRow)=>fetch("/api/birds",{method:"PUT",headers:apiHeaders(),body:JSON.stringify(bird)}).catch(()=>null);
const forgetBird=(name:string)=>fetch(`/api/birds?name=${encodeURIComponent(name)}`,{method:"DELETE",headers:apiHeaders()}).catch(()=>null);
