function SimTreeNode({name,sex,meta,subject=false,onOpen}:{name:string;sex?:Sex;meta?:string;subject?:boolean;onOpen?:()=>void}){return <button type="button" className={`sim-tree-node ${subject?"subject":sex==="Fêmea"?"female":"male"} ${name?"":"unknown"} ${onOpen?"clickable":""}`} onClick={onOpen} disabled={!onOpen}><strong>{name||"Origem natural (mateiro)"}</strong>{meta&&<span>{meta}</span>}</button>}
function TreeSimulator({birds,male,female,setMale,setFemale,openDiagnosis}:{birds:BirdRow[];male:string;female:string;setMale:(s:string)=>void;setFemale:(s:string)=>void;openDiagnosis:()=>void}){
 const males=birds.filter(b=>isActive(b)&&b.sex==="Macho"),females=birds.filter(b=>isActive(b)&&b.sex==="Fêmea"),mb=findBird(male,birds)??males[0],fb=findBird(female,birds)??females[0];
 const maleName=mb?.name||"",femaleName=fb?.name||"",result=genetic(maleName,femaleName,birds,false);
 const parentsOf=(name:string)=>{const row=findBird(name,birds);return[{name:row?.father||"",sex:"Macho" as Sex},{name:row?.mother||"",sex:"Fêmea" as Sex}]};
 const renderAncestor=(person:{name:string;sex:Sex},level:number,key:string):React.ReactNode=><div className="sim-branch" key={key}><SimTreeNode name={person.name} sex={person.sex}/>{level<3&&<div className={`sim-children ancestor-level-${level+1}`}>{parentsOf(person.name).map((ancestor,i)=>renderAncestor(ancestor,level+1,`${key}-${i}`))}</div>}</div>;
 const renderParent=(bird:BirdRow|undefined,sex:Sex,key:string)=><div className="sim-branch" key={key}><SimTreeNode name={bird?.name||""} sex={sex} meta={sex==="Macho"?"Pai":"Mãe"}/><div className="sim-children ancestor-level-1">{parentsOf(bird?.name||"").map((person,i)=>renderAncestor(person,1,`${key}-${i}`))}</div></div>;
 return <><Title tag="SIMULAÇÃO DE PEDIGREE" title="Simulador de árvore" text="Escolha o casal e veja a árvore completa do futuro filhote até os trisavós."/><section className="tree-simulator-controls"><label><span><Mars size={17}/> Macho</span><select value={maleName} onChange={e=>setMale(e.target.value)}>{males.map(b=><option key={b.id}>{b.name}</option>)}</select></label><b>×</b><label className="female"><span><Venus size={17}/> Fêmea</span><select value={femaleName} onChange={e=>setFemale(e.target.value)}>{females.map(b=><option key={b.id}>{b.name}</option>)}</select></label><div className="tree-simulator-summary"><small>Consanguinidade prevista</small><strong>{result.F.toFixed(2)}%</strong><em className={`badge ${result.severity}`}>{result.label}</em><button onClick={openDiagnosis}>Ver diagnóstico <ChevronRight size={15}/></button><button className="tree-print-button" onClick={()=>window.print()}><Printer size={15}/> Imprimir acasalamento</button></div></section><section className="tree-simulator-card"><div className="tree-print-header"><b>CRIADOURO APOLO — ACASALAMENTO GENÉTICO</b><span>{maleName} × {femaleName}</span><em>F previsto: {result.F.toFixed(2)}% • {result.label}</em></div><div className="tree-simulator-head"><div><span>LINHAGEM PROJETADA</span><h2>{maleName} × {femaleName}</h2></div><div className="tree-legend"><span><i className="male"/>Machos</span><span><i className="female"/>Fêmeas</span><span><i className="unknown"/>Não informado</span></div></div><div className="tree-scroll"><div className="tree-panorama"><div className="tree-generation-labels"><span>Filhote</span><span>Pais</span><span>Avós</span><span>Bisavós</span><span>Trisavós</span></div><div className="sim-tree"><SimTreeNode name="FILHOTE SIMULADO" subject meta={`${maleName} × ${femaleName}`}/><div className="sim-children parents">{renderParent(mb,"Macho","father")}{renderParent(fb,"Fêmea","mother")}</div></div></div></div><p className="tree-scroll-hint">No celular, deslize a árvore para os lados para visualizar todas as gerações.</p><div className="tree-print-guide"><b>Leitura do acasalamento</b><span>Esta árvore mostra a genealogia projetada do filhote. Machos e fêmeas são separados visualmente por sexo; “Origem natural (mateiro)” representa um fundador sem ascendência registrada.</span><strong>Consanguinidade prevista (F): {result.F.toFixed(2)}% — {result.label}</strong></div></section></>
}

type DNAAlleles=Record<string,[string,string]>;
type DNAProfile={cig:string;name:string;ring:string;sex?:string;sample?:string;lab?:string;notes?:string;alleles:DNAAlleles;updatedAt:string};
