 const [selectedMales,setSelectedMales]=useState(()=>males.map(b=>b.name)),[selectedFemales,setSelectedFemales]=useState(()=>females.map(b=>b.name)),[maxF,setMaxF]=useState(10),[maxPerMale,setMaxPerMale]=useState(3),[season,setSeason]=useState("Temporada 2027"),[saved,setSaved]=useState(false);
