 const plan=useMemo(()=>{const selectedM=new Set(selectedMales.map(nameKey)),selectedF=new Set(selectedFemales.map(nameKey)),candidates=males.filter(m=>selectedM.has(nameKey(m.name))).flatMap(m=>females.filter(f=>selectedF.has(nameKey(f.name))).map(f=>({male:m,female:f,...pairRating(m,f,birds)}))).filter(x=>!x.result.relationshipType&&x.result.F<=maxF).sort((a,b)=>b.score-a.score||a.result.F-b.result.F),usedFemales=new Set<string>(),maleUse=new Map<string,number>(),chosen:typeof candidates=[];for(const pair of candidates){const mk=nameKey(pair.male.name),fk=nameKey(pair.female.name);if(usedFemales.has(fk)||(maleUse.get(mk)||0)>=maxPerMale)continue;chosen.push(pair);usedFemales.add(fk);maleUse.set(mk,(maleUse.get(mk)||0)+1)}return chosen.sort((a,b)=>a.male.name.localeCompare(b.male.name,"pt-BR")||a.result.F-b.result.F)},[birds,males,females,selectedMales,selectedFemales,maxF,maxPerMale]);
