function ProductionHistory({bird,birds,summary,open}:{bird:BirdRow;birds:BirdRow[];summary:ReturnType<typeof productionSummary>;open:(name:string)=>void}){const recent=[...summary.rows].sort((a,b)=>(b[1]||"").localeCompare(a[1]||"")).slice(0,18),max=Math.max(...summary.byYear.map(x=>x[1]),1),parent=nameKey(bird.name),partners=[...summary.rows.reduce((map,row)=>{const partner=nameKey(row[3])===parent?row[4]:row[3];map.set(partner,(map.get(partner)||0)+1);return map},new Map<string,number>())].sort((a,b)=>b[1]-a[1]).slice(0,5);const birdByRing=(ring:string)=>birds.find(x=>ringKey(x.ring)===ringKey(ring));return <section className="production-history"><div className="production-title"><div><span>HISTÓRICO PRODUTIVO DOCUMENTADO</span><h2>{summary.total} filhos registrados</h2><p>Quantidade comprovada nas planilhas; não altera automaticamente a nota de qualidade genética.</p></div><div className="production-kpis"><b>{summary.males}<small>machos</small></b><b>{summary.females}<small>fêmeas</small></b><b>{summary.partners}<small>parceiros</small></b><b>{summary.years.length}<small>anos produtivos</small></b></div></div>{summary.total>0?<><div className="production-body"><div className="year-history"><strong>Produção por ano</strong><div>{summary.byYear.map(([year,count])=><span key={year}><small>{year}</small><i><u style={{height:`${Math.max(8,count/max*100)}%`}}/></i><b>{count}</b></span>)}</div></div><div className="partner-history"><strong>Principais parceiros</strong>{partners.map(([name,count])=><span key={name}><b>{name}</b><small>{count} filhos</small></span>)}</div></div><details className="offspring-list"><summary>Ver registros dos filhotes <b>{summary.total}</b></summary><div>{recent.map((row,index)=>{const linked=birdByRing(row[0]);const content=<><b>{linked?.name||row[0]||"Sem anilha"}</b><span>{row[1]?new Date(`${row[1]}T12:00:00`).toLocaleDateString("pt-BR"):"Data não informada"} • {row[5]==="M"?"Macho":row[5]==="F"?"Fêmea":"Sexo não informado"}</span><small>{row[3]} × {row[4]} • {row[6]}</small></>;return linked?<button key={row[0]+index} onClick={()=>open(linked.name)}>{content}<ChevronRight size={15}/></button>:<div key={row[0]+index}>{content}</div>})}{summary.total>recent.length&&<p>Mostrando os 18 registros mais recentes de {summary.total}.</p>}</div></details></>:<div className="production-empty">Nenhum nascimento localizado para esta ave nas duas planilhas enviadas.</div>}</section>}
