function AuditPanel({birds}:{birds:BirdRow[]}){
 const [q,setQ]=useState(""),[sex,setSex]=useState("Todos"),[sort,setSort]=useState("Menor pedigree conhecido");
 const a=auditPedigree(birds),active=birds.filter(isActive),rows=active.filter(b=>pedigreeQuality(b,birds).percent<100).filter(b=>(sex==="Todos"||b.sex===sex)&&(`${b.name} ${b.ring} ${b.lineage}`.toLowerCase().includes(q.toLowerCase()))).sort((x,y)=>sort==="Menor pedigree conhecido"?pedigreeQuality(x,birds).percent-pedigreeQuality(y,birds).percent:x.name.localeCompare(y.name));
 const complete=active.filter(b=>pedigreeQuality(b,birds).percent===100).length,partial=active.filter(b=>{const p=pedigreeQuality(b,birds).percent;return p>=50&&p<100}).length,weak=active.length-complete-partial;
 return <><Title tag="QUALIDADE DO BANCO" title="Auditoria genética do plantel" text="Revise os pedigrees que ainda precisam de complementação para aumentar a precisão das análises."/>
 <section className="audit-kpis"><div><ShieldCheck/><span>Qualidade geral<strong>{a.score}%</strong><small>integridade genealógica</small></span></div><div><CheckCircle2/><span>Pedigrees completos<strong>{complete}/{active.length}</strong><small>cobertura total</small></span></div><div><AlertTriangle/><span>A revisar<strong>{rows.length}</strong><small>pedigrees parciais</small></span></div><div><Dna/><span>Fundadores<strong>{active.filter(isFounder).length}</strong><small>origem natural</small></span></div></section><section className="audit-layout"><aside className="panel audit-summary"><p>STATUS DOS PEDIGREES</p><h2>Qualidade dos pedigrees</h2><div className="audit-status"><span><i className="ok"/>Completos <b>{complete}</b></span><span><i className="partial"/>Parciais <b>{partial}</b></span><span><i className="weak"/>Incompletos <b>{weak}</b></span></div><div className="donut" style={{background:`conic-gradient(#31bd78 0 ${complete/Math.max(1,active.length)*100}%,#9cdb7a 0 ${(complete+partial)/Math.max(1,active.length)*100}%,#ffbd42 0 100%)`}}><i><b>{active.length}</b><small>aves</small></i></div></aside>
 <section className="panel audit-main"><div className="audit-progress"><span><b>{Math.round(complete/Math.max(1,active.length)*100)}%</b> dos pedigrees totalmente conhecidos</span><i><u style={{width:`${complete/Math.max(1,active.length)*100}%`}}/></i></div><div className="card-heading"><div><p>PRIORIDADE DE REVISÃO</p><h2>Pedigrees a revisar</h2><small>Mateiros/fundadores são considerados origem conhecida e não são penalizados por ausência de pais.</small></div><ShieldCheck/></div><div className="audit-tools"><div className="search-box"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar nome, anilha ou linhagem..."/></div><select value={sex} onChange={e=>setSex(e.target.value)}><option>Todos</option><option>Macho</option><option>Fêmea</option></select><select value={sort} onChange={e=>setSort(e.target.value)}><option>Menor pedigree conhecido</option><option>Nome</option></select></div>
 <div className="audit-table"><div className="audit-head"><span>Ave</span><span>Anilha</span><span>Sexo</span><span>Pai</span><span>Mãe</span><span>Pedigree conhecido</span></div>{rows.slice(0,25).map(x=>{const p=pedigreeQuality(x,birds).percent;return <div className="audit-row" key={x.id}><span className="audit-bird"><img src={x.sex==="Macho"?"/bicudo-macho-recorte.png":"/bicudo-femea-recorte.png"} alt=""/><b>{x.name}</b></span><span>{x.ring||"—"}</span><span>{x.sex}</span><span>{x.father||"Mateiro"}</span><span>{x.mother||"Mateiro"}</span><span className="completion"><b>{p}%</b><i><u style={{width:`${p}%`}}/></i></span></div>})}</div></section>
 <aside className="panel audit-tips compact"><p>LEITURA DO ÍNDICE</p><h2>Como interpretar</h2><div className="audit-guide"><span><i className="ok"/>100%<small>Pedigree conhecido no horizonte analisado.</small></span><span><i className="partial"/>50–99%<small>Há ancestrais conhecidos, mas ainda existem lacunas.</small></span><span><i className="weak"/>&lt;50%<small>Prioridade para revisão documental.</small></span></div><div className="founder-note"><b>🌿 Origem natural (mateiro)</b><small>É tratado como fundador genealógico. A ausência de pais não reduz sua qualidade cadastral.</small></div></aside></section></>
}
function BirdDetail({birds,name,go,setMale,setFemale,setPedigreeTarget}:{birds:BirdRow[];name:string;go:(s:string)=>void;setMale:(s:string)=>void;setFemale:(s:string)=>void;setPedigreeTarget:(s:string)=>void}){
 const b=findBird(name,birds)||birds.find(isBreedable);if(!b)return null;
 const prod=productionSummary(b.name),quality=pedigreeQuality(b,birds),merit=birdMerit(b);
 const [dnaProfile,setDnaProfile]=useState<DNAProfile|null>(null),[dnaOpen,setDnaOpen]=useState(false);
 useEffect(()=>{fetch("/api/dna-profiles",{headers:apiHeaders()}).then(r=>r.ok?r.json():{profiles:[]}).then(d=>setDnaProfile((d.profiles||[]).find((p:DNAProfile)=>nameKey(p.name)===nameKey(b.name)||ringKey(p.ring||"")===ringKey(b.ring||""))||null)).catch(()=>{})},[b.name,b.ring]);
 const mates=birds.filter(x=>isActive(x)&&x.sex!==b.sex).map(x=>{const male=b.sex==="Macho"?b:x,female=b.sex==="Fêmea"?b:x;return{bird:x,...pairRating(male,female,birds)}}).filter(x=>!x.result.relationshipType).sort((a,c)=>c.score-a.score||a.result.F-c.result.F).slice(0,5);
 const diagnose=(mate:BirdRow)=>{if(b.sex==="Macho"){setMale(b.name);setFemale(mate.name)}else{setMale(mate.name);setFemale(b.name)}go("Calculadora genética")};
 return <><Title tag="FICHA INDIVIDUAL" title={b.name} text="Prontuário genealógico, produtivo e genético da ave."/>
 <section className="bird-profile-hero"><div className="bird-profile-photo"><img src={b.sex==="Fêmea"?"/bicudo-femea.png":"/bicudo-macho.jpg"} alt={b.name}/><span>{b.sex}</span></div><div className="bird-profile-info"><div className="bird-profile-kicker">FICHA INDIVIDUAL</div><div className="bird-profile-name"><h2>{b.name}</h2><span>{b.status}</span></div><div className="bird-profile-data"><div><small>ANILHA</small><b>{b.ring||"—"}</b></div><div><small>LINHAGEM</small><b>{b.lineage||"—"}</b></div><div><small>PAI</small><b>{b.father||"—"}</b></div><div><small>MÃE</small><b>{b.mother||"—"}</b></div></div><button className="profile-pedigree-btn" onClick={()=>{setPedigreeTarget(b.name);go("Pedigrees")}}><GitBranch size={16}/> Ver pedigree completo</button></div><div className="bird-profile-metrics"><h3>Resumo genético</h3><div><Stat n={quality.percent+"%"} label="Pedigree"/><Stat n={prod.total} label="Filhos"/><Stat n={prod.partners} label="Parceiros"/><Stat n={merit.score===null?"—":Math.round(merit.score)} label="Mérito"/></div></div></section>
 <div className="bird-profile-tabs"><button onClick={()=>document.querySelector(".bird-profile-hero")?.scrollIntoView({behavior:"smooth",block:"start"})}>Visão geral</button><button onClick={()=>{setPedigreeTarget(b.name);go("Pedigrees")}}>Pedigree</button><button onClick={()=>document.querySelector(".bird-production-card")?.scrollIntoView({behavior:"smooth",block:"start"})}>Produção</button><button className="active" onClick={()=>{setDnaOpen(true);setTimeout(()=>document.querySelector(".bird-dna-card")?.scrollIntoView({behavior:"smooth",block:"start"}),50)}}>DNA / CIG</button><button onClick={()=>document.querySelector(".bird-production-card")?.scrollIntoView({behavior:"smooth",block:"start"})}>Histórico</button></div><section className="panel bird-dna-card"><div className="bird-dna-card-head"><div><Dna/><span><small>DNA / CIG</small><h2>Perfil molecular</h2><p>{dnaProfile?"Perfil molecular cadastrado e disponível para comparação de parentesco.":"Esta ave ainda não possui perfil molecular cadastrado."}</p></span></div><button className="bird-dna-toggle" onClick={()=>setDnaOpen(v=>!v)}>{dnaOpen?"Fechar":dnaProfile?"Ver / editar CIG":"Adicionar CIG / DNA"}</button></div>{dnaProfile&&!dnaOpen&&<div className="bird-dna-summary"><div><small>CIG</small><b>{dnaProfile.cig}</b></div><div><small>AMOSTRA</small><b>{dnaProfile.sample||"—"}</b></div><div><small>STR PREENCHIDOS</small><b>{dnaMarkers.filter(m=>dnaProfile.alleles?.[m]?.some(Boolean)).length}/15</b></div><div><small>LABORATÓRIO</small><b>{dnaProfile.lab||"Nova Unigen"}</b></div></div>}{dnaOpen&&<BirdDNAEditor bird={b} initial={dnaProfile} onSaved={p=>{setDnaProfile(p);setDnaOpen(false)}}/>}</section>
 <section className="panel"><div className="card-heading"><div><p>ACASALAMENTO BIDIRECIONAL</p><h2>Melhores parceiros para {b.name}</h2></div><Sparkles/></div>{mates.map((x,i)=><button className="pair-line" key={x.bird.id} onClick={()=>diagnose(x.bird)}><span><b>#{i+1} {x.bird.name}</b><small> • pedigree {x.result.confidence}% • escore {x.score}</small></span><em>F {x.result.F.toFixed(2)}%</em><ChevronRight size={17}/></button>)}</section>
 <section className="panel bird-production-card"><div className="card-heading"><div><p>PRODUÇÃO HISTÓRICA</p><h2>Descendência registrada</h2></div><BarChart3/></div><div className="stats"><Stat n={prod.total} label="Total"/><Stat n={prod.males} label="Machos"/><Stat n={prod.females} label="Fêmeas"/><Stat n={prod.years.length} label="Anos com produção"/></div></section></>
}

function BirdDNAEditor({bird,initial,onSaved}:{bird:BirdRow;initial:DNAProfile|null;onSaved:(p:DNAProfile)=>void}){
 const [p,setP]=useState<DNAProfile>(()=>initial?JSON.parse(JSON.stringify(initial)):{cig:"",name:bird.name,ring:bird.ring||"",sample:"",lab:"Nova Unigen",notes:"",alleles:emptyDNA(),updatedAt:""}),[busy,setBusy]=useState(false);
 const [pdfBusy,setPdfBusy]=useState(false),[pdfMsg,setPdfMsg]=useState("");
 const loadScript=(src:string,id:string)=>new Promise<void>((resolve,reject)=>{if(document.getElementById(id)){resolve();return}const s=document.createElement("script");s.id=id;s.src=src;s.onload=()=>resolve();s.onerror=()=>reject(new Error("Falha ao carregar leitor OCR."));document.head.appendChild(s)});
 const parseOCR=(raw:string)=>{const text=raw.replace(/[|]/g," ").replace(/\s+/g," ");const alleles=emptyDNA();let filled=0;const locus=/\b(Oa2|Oa7|Oa26|Oa35|U[NM][S5]|U[NM][7]|U[NM][1Il]0|U[NM][1Il]3|U[NM][1Il]4|U[NM][1Il]5|U[NM][1Il]9|U[NM]21|U[NM]30|U[NM]34|U[NM]38)\b/gi,found=[...text.matchAll(locus)];const canon=(v:string)=>v.toUpperCase().replace(/^UM/,"UN").replace(/[IL]/g,"1").replace("UNS","UN5");for(let i=0;i<found.length;i++){const m=canon(found[i][1]),next=found[i+1]?.index??text.length,seg=text.slice((found[i].index||0)+found[i][0].length,Math.min(next,(found[i].index||0)+80)),nums=seg.match(/\b\d{1,3}\b|-/g)||[];if(dnaMarkers.includes(m)&&nums.length){const first=nums[0]??"",second=nums[1]??"";alleles[m]=[first==="-"?"":first,second==="-"?"":second];filled++}}if(filled<5){const markerLine=text.match(/(?:Loco|Locus)[\s\S]{0,220}?(?:Alelos?|Alleles?)[\s:]*([\d\s\/-]{20,180})/i);if(markerLine){const vals=markerLine[1].match(/\d{1,3}\s*[\/-]\s*\d{1,3}|\d{1,3}\s*[\/-]\s*-|\d{1,3}/g)||[];dnaMarkers.forEach((m,i)=>{const pair=vals[i]?.match(/(\d{1,3})(?:\s*[\/-]\s*(\d{1,3}|-))?/);if(pair&&!alleles[m][0]){alleles[m]=[pair[1],pair[2]&&pair[2]!=="-"?pair[2]:""];filled++}})}}const ring=(text.match(/ID\s*\(?anilha\)?\s*[:\-]?\s*([A-Z0-9 .\/\-]{5,40}?)(?=Nome|Data)/i)?.[1]||"").trim(),sample=(text.match(/(?:N[ºo°]?\s*da\s*Amostra|Amostra)\s*[:\-]?\s*([A-Z0-9\-]+)/i)?.[1]||"").trim();return{ring,sample,alleles,filled}};
 const importPDF=async(file:File)=>{setPdfBusy(true);setPdfMsg("Preparando leitura visual do PDF…");try{await loadScript("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js","apolo-pdfjs");await loadScript("https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js","apolo-tesseract");const w=window as any;w.pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const pdf=await w.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let best:any=null;for(let n=1;n<=pdf.numPages;n++){setPdfMsg(`Lendo página ${n} de ${pdf.numPages}…`);const page=await pdf.getPage(n),viewport=page.getViewport({scale:5}),canvas=document.createElement("canvas");canvas.width=Math.round(viewport.width);canvas.height=Math.round(viewport.height);const ctx=canvas.getContext("2d");if(!ctx)continue;ctx.imageSmoothingEnabled=false;await page.render({canvasContext:ctx,viewport}).promise;const ocr=await w.Tesseract.recognize(canvas,"eng",{logger:(m:any)=>{if(m.status==="recognizing text")setPdfMsg(`Lendo números do CIG… ${Math.round((m.progress||0)*100)}%`)}});const parsed=parseOCR(ocr.data.text||"");if(!best||parsed.filled>best.filled)best=parsed}if(!best||best.filled<1)throw new Error("Não consegui localizar os números do CIG nesta imagem. Tente um print ocupando a página inteira.");setP(x=>({...x,name:bird.name,ring:bird.ring||best.ring||x.ring,sample:best.sample||x.sample,lab:"Nova Unigen",notes:"Importado por leitura visual do CIG Nova Unigen — confira antes de salvar.",alleles:best.alleles}));setPdfMsg(`Leitura concluída: ${best.filled}/15 marcadores preenchidos. Confira os valores; os campos não reconhecidos podem ser completados manualmente.`)}catch(e){setPdfMsg(e instanceof Error?e.message:"Não foi possível ler visualmente o PDF.")}finally{setPdfBusy(false)}};
 useEffect(()=>{setP(initial?JSON.parse(JSON.stringify(initial)):{cig:"",name:bird.name,ring:bird.ring||"",sample:"",lab:"Nova Unigen",notes:"",alleles:emptyDNA(),updatedAt:""})},[bird.name,initial]);
 const save=async()=>{if(!p.cig.trim()){alert("Informe o CIG da ave.");return}setBusy(true);const profile={...p,name:bird.name,ring:bird.ring||p.ring,cig:p.cig.trim(),updatedAt:new Date().toISOString()};const r=await fetch("/api/dna-profiles",{method:"PUT",headers:apiHeaders(),body:JSON.stringify(profile)});setBusy(false);if(!r.ok){const d=await r.json().catch(()=>({}));if(r.status===401){localStorage.removeItem("apolo-access-token");alert("Sua sessão expirou. Entre novamente no sistema e tente salvar o CIG.");window.location.reload();return}alert(`Não foi possível salvar o perfil DNA.${d.error?`\n\n${d.error}`:""}`);return}onSaved(profile)};
 return <div className="bird-dna-editor"><div className="bird-dna-import"><div><b>Importar CIG da Nova Unigen</b><small>O sistema lê o PDF e preenche os marcadores automaticamente.</small></div><label>{pdfBusy?"Lendo PDF…":"Importar PDF"}<input type="file" accept="application/pdf" disabled={pdfBusy} onChange={e=>{const file=e.target.files?.[0];if(file)importPDF(file);e.currentTarget.value=""}}/></label>{pdfMsg&&<p>{pdfMsg}</p>}</div><div className="bird-dna-fields"><label><span>CIG</span><input placeholder="Identificação genética" value={p.cig} onChange={e=>setP(x=>({...x,cig:e.target.value}))}/></label><label><span>Nº da amostra</span><input placeholder="Ex.: NU312074" value={p.sample||""} onChange={e=>setP(x=>({...x,sample:e.target.value}))}/></label><label><span>Laboratório</span><input value={p.lab||""} onChange={e=>setP(x=>({...x,lab:e.target.value}))}/></label></div><div className="bird-dna-marker-title"><div><b>Perfil STR</b><small>15 marcadores moleculares</small></div><span>{dnaMarkers.filter(m=>p.alleles[m]?.some(Boolean)).length}/15 preenchidos</span></div><div className="bird-dna-table-wrap"><table className="bird-dna-table"><thead><tr><th>Marcador</th><th>Alelo 1</th><th>Alelo 2</th></tr></thead><tbody>{dnaMarkers.map(m=><tr key={m}><th>{m}</th>{[0,1].map(i=><td key={i}><input placeholder="—" value={p.alleles[m]?.[i]||""} onChange={e=>setP(x=>({...x,alleles:{...x.alleles,[m]:(x.alleles[m]||["",""]).map((a,j)=>j===i?e.target.value.trim():a) as [string,string]}}))}/></td>)}</tr>)}</tbody></table></div><label className="bird-dna-notes"><span>Observações</span><textarea placeholder="Informações adicionais do laudo…" value={p.notes||""} onChange={e=>setP(x=>({...x,notes:e.target.value}))}/></label><div className="bird-dna-note"><ShieldCheck size={17}/><span><b>Importante:</b> confira os alelos com o laudo original da Nova Unigen antes de salvar ou utilizar o perfil em uma comparação de parentesco.</span></div><div className="bird-dna-actions"><button type="button" className="dna-clear" onClick={()=>setP(x=>({...x,cig:"",sample:"",notes:"",alleles:emptyDNA()}))}><RotateCcw size={16}/> Limpar campos</button><button disabled={busy} onClick={save}><ShieldCheck size={16}/>{busy?"Salvando…":"Salvar CIG"}</button></div></div>
}

function PopulationGenetics({birds,choose}:{birds:BirdRow[];choose:(m:string,f:string)=>void}){
 const [tab,setTab]=useState<"overview"|"composition"|"lineages"|"kinship"|"strategy">("overview");
 const active=birds.filter(isActive),males=active.filter(b=>b.sex==="Macho"),females=active.filter(b=>b.sex==="Fêmea"),bases=plantelConcentration(active).slice(0,7);
 const pairs=males.flatMap(m=>females.map(f=>({m,f,r:genetic(m.name,f.name,birds,false)}))).filter(x=>!x.r.relationshipType),avg=pairs.length?pairs.reduce((a,x)=>a+x.r.F,0)/pairs.length:0;
 const bands=[pairs.filter(x=>x.r.F<3).length,pairs.filter(x=>x.r.F>=3&&x.r.F<6.25).length,pairs.filter(x=>x.r.F>=6.25&&x.r.F<12.5).length,pairs.filter(x=>x.r.F>=12.5&&x.r.F<=20).length,pairs.filter(x=>x.r.F>20).length],max=Math.max(...bands,1);
 const rank=(rows:BirdRow[],opposite:BirdRow[])=>rows.map(x=>({b:x,avg:opposite.length?opposite.reduce((a,y)=>a+genetic(x.sex==="Macho"?x.name:y.name,x.sex==="Macho"?y.name:x.name,birds,false).F,0)/opposite.length:0})).sort((a,b)=>a.avg-b.avg);
 const mr=rank(males,females),fr=rank(females,males);
 return <><Title tag="GENÉTICA POPULACIONAL" title="Genética populacional" text="Visão global da concentração de sangue, parentesco e oportunidades de abertura genética no plantel."/>
 <section className="module-tabs"><button className={tab==="overview"?"active":""} onClick={()=>setTab("overview")}>Visão geral</button><button className={tab==="composition"?"active":""} onClick={()=>setTab("composition")}>Composição genética</button><button className={tab==="lineages"?"active":""} onClick={()=>setTab("lineages")}>Contribuição das linhagens</button><button className={tab==="kinship"?"active":""} onClick={()=>setTab("kinship")}>Parentesco entre indivíduos</button><button className={tab==="strategy"?"active":""} onClick={()=>setTab("strategy")}>Cenários e estratégias</button></section>
 {tab==="overview"&&<><section className="population-kpis"><div><Dna/><span>F médio<strong>{avg.toFixed(2)}%</strong><small>{pairs.length} combinações</small></span></div><div><CheckCircle2/><span>Até 6,25%<strong>{bands[0]+bands[1]}</strong><small>Boa oportunidade</small></span></div><div><AlertTriangle/><span>6,25–12,5%<strong>{bands[2]}</strong><small>Atenção moderada</small></span></div><div><AlertTriangle/><span>Acima de 12,5%<strong>{bands[3]+bands[4]}</strong><small>Maior atenção</small></span></div><div><GitBranch/><span>Bases genéticas<strong>{bases.length}</strong><small>Fontes principais</small></span></div></section><section className="population-grid"><article className="panel population-chart"><h2>Distribuição da consanguinidade</h2><div className="bar-chart">{bands.map((n,i)=><div key={i}><b>{n}</b><i><u style={{height:`${Math.max(8,n/max*100)}%`}}/></i><span>{["<3%","3–6,25%","6,25–12,5%","12,5–20%",">20%"][i]}</span></div>)}</div></article><article className="panel"><h2>Principais fontes de sangue</h2>{bases.map(x=><div className="blood-bar" key={x.name}><b>{x.name}</b><i><u style={{width:`${Math.min(100,x.value*3)}%`}}/></i><strong>{x.value.toFixed(1)}%</strong></div>)}</article></section></>}
 {tab==="composition"&&<section className="panel"><div className="card-heading"><div><p>COMPOSIÇÃO DO PLANTEL</p><h2>Estrutura genética atual</h2></div><Dna/></div><div className="stats"><Stat n={active.length} label="Aves ativas"/><Stat n={males.length} label="Machos"/><Stat n={females.length} label="Fêmeas"/><Stat n={bases.length} label="Bases principais"/></div>{bases.map(x=><div className="blood-bar" key={x.name}><b>{x.name}</b><i><u style={{width:`${Math.min(100,x.value*3)}%`}}/></i><strong>{x.value.toFixed(1)}%</strong></div>)}</section>}
 {tab==="lineages"&&<section className="panel"><div className="card-heading"><div><p>LINHAGENS</p><h2>Contribuição relativa das bases</h2></div><BarChart3/></div>{bases.map((x,i)=><div className="rank-row" key={x.name}><b>#{i+1} {x.name}</b><i><u style={{width:`${Math.min(100,x.value*3)}%`}}/></i><strong>{x.value.toFixed(1)}%</strong></div>)}</section>}
 {tab==="kinship"&&<section className="population-ranks"><article className="panel"><h2>Machos — menor parentesco médio</h2>{mr.slice(0,12).map((x,i)=><div className="rank-button" key={x.b.id}><b>#{i+1} {x.b.name}</b><strong>{x.avg.toFixed(2)}%</strong></div>)}</article><article className="panel"><h2>Fêmeas — menor parentesco médio</h2>{fr.slice(0,12).map((x,i)=><div className="rank-button" key={x.b.id}><b>#{i+1} {x.b.name}</b><strong>{x.avg.toFixed(2)}%</strong></div>)}</article></section>}
 {tab==="strategy"&&<section className="strategy-panel"><div className="strategy-head"><div><p>CENÁRIOS E ESTRATÉGIAS</p><h2>Acasalamentos para maior abertura genética</h2><span>Combinações priorizadas pelo menor parentesco genealógico. Clique em um casal para abrir o diagnóstico completo.</span></div><Sparkles/></div><div className="strategy-kpis"><span><b>{mr.length}</b><small>machos avaliados</small></span><span><b>{females.length}</b><small>fêmeas disponíveis</small></span><span><b>{pairs.filter(x=>x.r.F<=6.25).length}</b><small>combinações até 6,25%</small></span></div><div className="strategy-list">{mr.slice(0,12).map((x,i)=>{const mate=[...females].sort((a,b)=>genetic(x.b.name,a.name,birds,false).F-genetic(x.b.name,b.name,birds,false).F)[0];if(!mate)return null;const r=genetic(x.b.name,mate.name,birds,false),cls=r.F<3?"excellent":r.F<=6.25?"good":"attention";return <button className="strategy-row" key={x.b.id} onClick={()=>choose(x.b.name,mate.name)}><span className="strategy-rank">#{i+1}</span><span className="strategy-birds"><img src="/bicudo-macho-recorte.png" alt="Macho"/><b>{x.b.name}</b><i>×</i><img src="/bicudo-femea-recorte.png" alt="Fêmea"/><b>{mate.name}</b><small>Ver diagnóstico completo <ChevronRight size={14}/></small></span><span className={`strategy-f ${cls}`}><small>F previsto</small><strong>{r.F.toFixed(2)}%</strong></span></button>})}</div></section>}</>
}
function ConservationPanel({birds}:{birds:BirdRow[]}){
 const active=birds.filter(isActive),males=active.filter(b=>b.sex==="Macho"),females=active.filter(b=>b.sex==="Fêmea");
 const [maleFilter,setMaleFilter]=useState("Todos"),[femaleFilter,setFemaleFilter]=useState("Todas"),[selectedM,setSelectedM]=useState<string[]>([]),[selectedF,setSelectedF]=useState<string[]>([]),[maleOpen,setMaleOpen]=useState(false),[femaleOpen,setFemaleOpen]=useState(false),[simMale,setSimMale]=useState(""),[conTab,setConTab]=useState<"matrix"|"contribution"|"risks"|"removal"|"diversity">("matrix");
 const allPairs=males.flatMap(m=>females.map(f=>({m,f,r:genetic(m.name,f.name,birds,false)}))).filter(x=>!x.r.relationshipType);
 const baseAvg=allPairs.length?allPairs.reduce((a,x)=>a+x.r.F,0)/allPairs.length:0;
 const bands=[{label:"Muito baixo",range:"< 3%",test:(v:number)=>v<3,cls:"f-vlow"},{label:"Baixo",range:"3 – 6,25%",test:(v:number)=>v>=3&&v<6.25,cls:"f-low"},{label:"Moderado",range:"6,25 – 12,5%",test:(v:number)=>v>=6.25&&v<12.5,cls:"f-mid"},{label:"Alto",range:"12,5 – 20%",test:(v:number)=>v>=12.5&&v<=20,cls:"f-high"},{label:"Muito alto",range:"> 20%",test:(v:number)=>v>20,cls:"f-vhigh"}];
 const bases=plantelConcentration(active).slice(0,8),bottlenecks=bases.filter(x=>x.value>=20);
 const impact=males.map(m=>{const pairs=males.filter(x=>x.id!==m.id).flatMap(mm=>females.map(ff=>genetic(mm.name,ff.name,birds,false))).filter(r=>!r.relationshipType),avg=pairs.length?pairs.reduce((a,r)=>a+r.F,0)/pairs.length:0;return{bird:m,avg,delta:avg-baseAvg}}).sort((a,b)=>b.delta-a.delta);
 const ranking=males.map(m=>({m,avg:females.length?females.reduce((a,f)=>a+genetic(m.name,f.name,birds,false).F,0)/females.length:0})).sort((a,b)=>a.avg-b.avg);
 const shownM=selectedM.length?males.filter(x=>selectedM.includes(x.name)):maleFilter==="Todos"?males:males.filter(x=>x.name===maleFilter),shownF=selectedF.length?females.filter(x=>selectedF.includes(x.name)):femaleFilter==="Todas"?females:females.filter(x=>x.name===femaleFilter); const toggleSel=(name:string,setter:React.Dispatch<React.SetStateAction<string[]>>)=>setter(v=>v.includes(name)?v.filter(x=>x!==name):[...v,name]);
 const sim=impact.find(x=>x.bird.name===simMale);
 return <><Title tag="CONSERVAÇÃO GENÉTICA" title="Conservação genética" text="Risco de consanguinidade, gargalos e decisões para preservar diversidade."/>
 <section className="conservation-tabs"><button className={conTab==="matrix"?"active":""} onClick={()=>setConTab("matrix")}>Matriz de consanguinidade</button><button className={conTab==="contribution"?"active":""} onClick={()=>setConTab("contribution")}>Contribuição genética</button><button className={conTab==="risks"?"active":""} onClick={()=>setConTab("risks")}>Gargalos e riscos</button><button className={conTab==="removal"?"active":""} onClick={()=>setConTab("removal")}>Simulação de retirada</button><button className={conTab==="diversity"?"active":""} onClick={()=>setConTab("diversity")}>Diversidade do plantel</button></section>
 {conTab==="matrix"&&<section className="matrix-pro"><div className="matrix-main"><div className="matrix-pro-head"><div><p>MATRIZ GLOBAL</p><h2>Consanguinidade prevista (%)</h2></div><div className="matrix-print-title"><b>CRIADOURO APOLO — MATRIZ GLOBAL DE CONSANGUINIDADE</b><span>Planejamento genético • F previsto (%)</span></div><div className="matrix-filters multi"><div className="multi-select"><button type="button" onClick={()=>setMaleOpen(v=>!v)}>{selectedM.length?`${selectedM.length} machos selecionados`:"Selecionar machos"} <ChevronDown size={15}/></button>{maleOpen&&<div className="multi-menu"><label><input type="checkbox" checked={selectedM.length===males.length} onChange={()=>setSelectedM(selectedM.length===males.length?[]:males.map(x=>x.name))}/> Todos os machos</label>{males.map(x=><label key={x.id}><input type="checkbox" checked={selectedM.includes(x.name)} onChange={()=>toggleSel(x.name,setSelectedM)}/>{x.name}</label>)}</div>}</div><div className="multi-select"><button type="button" onClick={()=>setFemaleOpen(v=>!v)}>{selectedF.length?`${selectedF.length} fêmeas selecionadas`:"Selecionar fêmeas"} <ChevronDown size={15}/></button>{femaleOpen&&<div className="multi-menu"><label><input type="checkbox" checked={selectedF.length===females.length} onChange={()=>setSelectedF(selectedF.length===females.length?[]:females.map(x=>x.name))}/> Todas as fêmeas</label>{females.map(x=><label key={x.id}><input type="checkbox" checked={selectedF.includes(x.name)} onChange={()=>toggleSel(x.name,setSelectedF)}/>{x.name}</label>)}</div>}</div>{(selectedM.length>0||selectedF.length>0)&&<button type="button" className="clear-matrix" onClick={()=>{setSelectedM([]);setSelectedF([])}}>Limpar seleção</button>}</div></div><div className="heatmap-screen"><div className="heatmap-scroll"><table className="heatmap"><thead><tr><th>Machos</th>{shownF.map(f=><th key={f.id}>{f.name}</th>)}</tr></thead><tbody>{shownM.map(m=><tr key={m.id}><th>{m.name}</th>{shownF.map(f=>{const v=genetic(m.name,f.name,birds,false).F,b=bands.find(x=>x.test(v));return <td className={b?.cls} key={f.id}>{v.toFixed(1)}</td>})}</tr>)}</tbody></table></div></div><div className="print-matrix-blocks">{Array.from({length:Math.ceil(shownF.length/10)},(_,block)=>{const group=shownF.slice(block*10,block*10+10);return <section className="print-matrix-block" key={block}><div className="print-block-head"><b>Fêmeas {block*10+1}–{block*10+group.length}</b><span>F previsto (%) • {group.length} fêmeas</span></div><table><thead><tr><th>Macho</th>{group.map(f=><th key={f.id}>{f.name}</th>)}</tr></thead><tbody>{shownM.map(m=><tr key={m.id}><th>{m.name}</th>{group.map(f=>{const v=genetic(m.name,f.name,birds,false).F,b=bands.find(x=>x.test(v));return <td className={b?.cls} key={f.id}>{v.toFixed(1)}</td>})}</tr>)}</tbody></table></section>})}<div className="print-guide"><div className="print-guide-title"><b>COMO USAR ESTA MATRIZ</b><span>Procure o macho na linha e a fêmea na coluna. O número no encontro é o F previsto do filhote.</span></div><div className="print-legend"><span><i className="f-vlow"/><b>&lt;3%</b><small>Excelente abertura</small></span><span><i className="f-low"/><b>3–6,25%</b><small>Boa opção</small></span><span><i className="f-mid"/><b>6,25–12,5%</b><small>Atenção</small></span><span><i className="f-high"/><b>12,5–20%</b><small>Evitar se houver alternativa</small></span><span><i className="f-vhigh"/><b>&gt;20%</b><small>Não recomendado</small></span></div><p><strong>Regra prática:</strong> prefira células verdes. Amarelo exige avaliação do pedigree; laranja e vermelho indicam maior concentração de parentesco. F = coeficiente de consanguinidade previsto.</p></div></div><div className="matrix-print-actions"><button type="button" onClick={()=>window.print()}><Printer size={16}/> Imprimir matriz A4</button><small>A impressão usa apenas os machos e fêmeas selecionados acima.</small></div></div><aside className="matrix-side"><h3>Legenda de risco</h3>{bands.map(b=><div className="legend-row" key={b.label}><i className={b.cls}/><span>{b.label}</span><b>{b.range}</b></div>)}</aside></section>}
 {conTab==="contribution"&&<section className="panel"><div className="card-heading"><div><p>CONTRIBUIÇÃO GENÉTICA</p><h2>Representação das bases no plantel</h2></div><BarChart3/></div>{bases.map((x,i)=><div className="blood-bar" key={x.name}><b>#{i+1} {x.name}</b><i><u style={{width:`${Math.min(100,x.value*3)}%`}}/></i><strong>{x.value.toFixed(1)}%</strong></div>)}</section>}
 {conTab==="risks"&&<><section className="conservation-kpis"><div><AlertTriangle/><span>Gargalos ≥20%<strong>{bottlenecks.length}</strong><small>bases concentradas</small></span></div><div><AlertTriangle/><span>Casais &gt;20%<strong>{allPairs.filter(x=>x.r.F>20).length}</strong><small>risco muito alto</small></span></div><div><Dna/><span>F médio<strong>{baseAvg.toFixed(2)}%</strong><small>plantel atual</small></span></div></section><section className="panel"><h2>Gargalos detectados</h2>{bottlenecks.length?bottlenecks.map(x=><div className="pair-line" key={x.name}><span><b>{x.name}</b><small>contribuição elevada</small></span><em>{x.value.toFixed(1)}%</em></div>):<p>Nenhum gargalo acima de 20%.</p>}</section></>}
 {conTab==="removal"&&<section className="panel"><div className="card-heading"><div><p>SIMULAÇÃO</p><h2>Efeito da retirada de um reprodutor</h2></div><Dna/></div><select className="sim-select" value={simMale} onChange={e=>setSimMale(e.target.value)}><option value="">Selecione um macho...</option>{males.map(x=><option key={x.id}>{x.name}</option>)}</select>{sim&&<div className="sim-result"><span>F atual<strong>{baseAvg.toFixed(2)}%</strong></span><span>F sem {sim.bird.name}<strong>{sim.avg.toFixed(2)}%</strong></span><span>Variação<strong>{sim.delta>0?"+":""}{sim.delta.toFixed(2)} pp</strong></span></div>}<div style={{marginTop:18}}>{impact.slice(0,12).map(x=><div className="pair-line" key={x.bird.id}><b>{x.bird.name}</b><em>{x.delta>0?"+":""}{x.delta.toFixed(2)} pp</em></div>)}</div></section>}
 {conTab==="diversity"&&<section className="population-ranks"><article className="panel"><h2>Reprodutores com maior abertura</h2>{ranking.slice(0,12).map((x,i)=><div className="rank-button" key={x.m.id}><b>#{i+1} {x.m.name}</b><strong>F médio {x.avg.toFixed(2)}%</strong></div>)}</article><article className="panel"><h2>Resumo da diversidade</h2><div className="stats"><Stat n={Math.max(0,100-baseAvg).toFixed(1)+"%"} label="Índice genealógico"/><Stat n={males.length} label="Machos"/><Stat n={females.length} label="Fêmeas"/><Stat n={bases.length} label="Bases"/></div></article></section>}</>
}
